addEventListener("load", () => { ST.init(); if (document.fonts) document.fonts.ready.then(() => ST.refresh()); setTimeout(() => ST.refresh(), 400); });
addEventListener("resize", reinit);
addEventListener("intro:exit", () => { if (window.gsap && FX.hero) gsap.delayedCall(0.2, () => FX.hero.play()); });
addEventListener("intro:done", () => ST.refresh());
matchMedia("(prefers-reduced-motion: reduce)").addEventListener("change", () => ST.init());
